create table if not exists public.hub_data_backend_configs (scope text primary key default 'global',active_backend text not null default 'supabase' check(active_backend in('supabase','external_postgres')),target_kind text not null default 'postgres' check(target_kind in('postgres','self_hosted_supabase')),target_name text not null default '',gateway_url text not null default '',database_name text not null default '',ssl_required boolean not null default true,status text not null default 'not_configured' check(status in('not_configured','configured','tested','migrating','ready','active','error','rollback')),gateway_fingerprint text not null default '',last_test_at timestamptz,activated_at timestamptz,previous_backend text not null default 'supabase',updated_by uuid references public.profiles(id) on delete set null,updated_at timestamptz not null default now());
create table if not exists public.hub_data_migration_runs (id uuid primary key default gen_random_uuid(),source_backend text not null default 'supabase',target_backend text not null default 'external_postgres',target_name text not null default '',status text not null default 'queued' check(status in('queued','preflight','schema','copying','verifying','ready','activated','failed','rolled_back')),started_at timestamptz not null default now(),completed_at timestamptz,created_by uuid not null references public.profiles(id) on delete restrict,table_counts jsonb not null default '{}'::jsonb,verification jsonb not null default '{}'::jsonb,error_message text not null default '',rollback_available boolean not null default true);
alter table public.hub_data_backend_configs enable row level security;alter table public.hub_data_migration_runs enable row level security;
grant select,insert,update,delete on public.hub_data_backend_configs to authenticated;grant select,insert,update on public.hub_data_migration_runs to authenticated;
create policy "pulse backend authenticated read" on public.hub_data_backend_configs for select to authenticated using(true);
create policy "pulse backend superadmin insert" on public.hub_data_backend_configs for insert to authenticated with check(public.vlacora_current_role()='superadmin');
create policy "pulse backend superadmin update" on public.hub_data_backend_configs for update to authenticated using(public.vlacora_current_role()='superadmin') with check(public.vlacora_current_role()='superadmin');
create policy "pulse backend superadmin delete" on public.hub_data_backend_configs for delete to authenticated using(public.vlacora_current_role()='superadmin');
create policy "pulse migration superadmin read" on public.hub_data_migration_runs for select to authenticated using(public.vlacora_current_role()='superadmin');
create policy "pulse migration superadmin insert" on public.hub_data_migration_runs for insert to authenticated with check(public.vlacora_current_role()='superadmin' and created_by=auth.uid());
create policy "pulse migration superadmin update" on public.hub_data_migration_runs for update to authenticated using(public.vlacora_current_role()='superadmin') with check(public.vlacora_current_role()='superadmin');
insert into public.hub_data_backend_configs(scope) values('global') on conflict(scope) do nothing;
